L17_1.m_Talk_THA = "\224\184\173\224\184\162\224\185\136\224\184\178\224\184\158\224\184\185\224\184\148\224\184\173\224\184\162\224\185\136\224\184\178\224\184\135\224\184\153\224\184\177\224\185\137\224\184\153 \224\184\161\224\184\177\224\184\153\224\184\162\224\184\178\224\184\129\224\184\151\224\184\181\224\185\136\224\184\136\224\184\176\224\184\149\224\184\173\224\184\154\224\185\129\224\184\151\224\184\153\224\184\132\224\184\184\224\184\147\224\184\173\224\184\162\224\185\136\224\184\178\224\184\135\224\184\149\224\184\173\224\184\153\224\184\153\224\184\181\224\185\137"
L17_1.m_Talk_VTN = "\196\144\225\187\171ng n\195\179i th\225\186\191. T\195\180i v\225\186\171n ch\198\176a tr\225\186\163 h\225\186\191t \195\162n t\195\172nh cho c\195\180 m\195\160."
L17_1.m_Talk_SCN = "\229\136\171\232\175\180\232\191\153\231\167\141\232\175\157\227\128\130\230\136\145\232\191\152\230\178\161\232\191\152\229\174\140\228\189\160\231\154\132\228\186\186\230\131\133\229\145\162\227\128\130"
