L18_1.m_Talk_SCN = "\226\128\166\226\128\166\233\130\163\230\136\145\232\181\176\228\186\134\227\128\130\228\189\160\229\165\189\229\165\189\228\188\145\230\129\175\239\188\140\232\180\157\231\189\151\229\176\188\229\141\161\227\128\130"
